// React package target (drop-in for Next.js, TanStack Start/Lovable, Vite/Bolt, v0, Claude Code/Codex):
// Tailwind v4 @theme + shadcn/ui variables from the tokens, the theme's CSS and fonts, one plain TSX
// component per section (props default to content JSON), page compositions, DESIGN.md, AGENTS.md and a
// shadcn registry (registry.json + r/*.json) so `npx shadcn add <url>` works. No framework scaffold.
import { urlMapper, mapIR, renderBody, readBin, bodyClass, legalLinks, pageTitle, LEGAL_TEXT, faviconSvg, legalRoutes, headAssets, headExtraBefore, headExtraAfter } from './common.js';
import { renderJsx, mapUrlsInHtml, camelItems, KK_STYLE_HELPER } from '../template.js';
import { pageHtml } from './html.js';
import { toTailwindTheme } from '../tokens/tailwind.js';
import { shadcnCss, shadcnRoles } from '../tokens/shadcn.js';
import { pascal } from '../ir.js';

export const meta = { id: 'react', tier: 1, status: 'ready', label: 'React package (Tailwind v4 @theme + shadcn/ui variables + TSX sections)', versions: 'react >= 18 (tested with 19), Tailwind CSS v4 optional, shadcn registry schema', editable: 'Texts live in components/content/*.json; the client edits only through the app they use (v0, Lovable, a CMS the developers attach). Without a CMS: agency or agent.' };

const containsSection = (n) => { let hit = false; (function w(x) { if (hit) return; if (x.kkSection) { hit = true; return; } (x.children || []).forEach(w); })(n); return hit; };
const tsKey = (k) => (/^[a-zA-Z_$][\w$]*$/.test(k) ? k : JSON.stringify(k));

function componentTsx(ir, sec, mapUrl) {
  const colls = sec.collections.map((c) => ir.collections[c]);
  const imports = [sec.props.length && `import data from './content/sections/${sec.name}.json';`, ...colls.map((c) => `import ${camelItems(c.name)}Data from './content/${c.name}.json';`)].filter(Boolean);
  const itemTypes = colls.map((c) => `export interface ${c.component}Item { id: string; order: number; ${c.fields.map((f) => `${tsKey(f.key)}?: string | null;`).join(' ')} }`);
  const fields = [...sec.props.map((p) => `  ${tsKey(p.key)}?: string | null;`), ...colls.map((c) => `  ${camelItems(c.name)}?: ${c.component}Item[];`)];
  const body = renderJsx(sec.node, { mapUrl });
  return `// ${sec.component}: section "${sec.name}". Generated by kk export; texts live in ./content.
${imports.join('\n')}
${itemTypes.join('\n')}
${body.includes('kkStyle(') ? KK_STYLE_HELPER : ''}export interface ${sec.component}Props {
${fields.join('\n') || '  // fixed markup, no props'}
}

export default function ${sec.component}(props: ${sec.component}Props = {}) {
${sec.props.length ? `  const p = { ...(data as Record<string, string | null>), ...props } as Record<string, any>;\n` : ''}${colls.map((c) => `  const ${camelItems(c.name)} = [...(props.${camelItems(c.name)} ?? (${camelItems(c.name)}Data as ${c.component}Item[]))].sort((a, b) => a.order - b.order) as any[];`).join('\n')}
  return (
${body}
  );
}
`;
}

function pageTsx(ir, page, fix) {
  const { renderJsx: _ } = { renderJsx };
  const used = new Set();
  const conv = (node) => node.children.map((c) => {
    if (c.type === 'el' && c.kkSection) { const s = ir.sections[c.kkSection]; used.add(s.component); return `<${s.component} />`; }
    if (c.type === 'el' && containsSection(c)) { const shell = renderJsx({ ...c, children: [], kkAttrs: null, kkInner: null, kkEach: null }, { mapUrl: urlMapper(ir, 'routes') }); return shell.replace(/\s*\/>$|><\/\w+>$/, '>') + conv(c) + `</${c.tag}>`; }
    if (c.type === 'comment') return '';
    if (c.type === 'text') return c.raw.trim() ? c.raw.replace(/[{}]/g, (x) => `{'${x}'}`) : '\n';
    return renderJsx(c, { mapUrl: urlMapper(ir, 'routes') });
  }).join('');
  const body = conv(page.body);
  const name = pascal(page.slug) + 'Page';
  return { name, code: `// Page "${page.slug}" (${page.path}). Generated by kk export. Wrap it in your app's layout/route.
${[...used].map((c) => `import ${c} from '../components/${c}';`).join('\n')}

export const meta = { title: ${JSON.stringify(pageTitle(ir, page))}, description: ${JSON.stringify(page.description)}, path: ${JSON.stringify(page.path)}, bodyClassName: ${JSON.stringify(bodyClass(page))}, bodyId: ${JSON.stringify(/\bid="([^"]*)"/.exec(page.bodyOpen || '')?.[1] || '')} };

export default function ${name}() {
  return (
    <>
${body}
    </>
  );
}
` };
}

export async function exportTarget(ir, opts = {}) {
  const files = new Map(), notes = [];
  const mapUrl = urlMapper(ir, 'routes');
  const routes = { ...legalRoutes(ir, '/impressum/', '/datenschutz/'), home: '/' };
  // theme paths -> package paths: CSS and fonts under styles/, everything else under public/
  const pkgPath = (rel) => (rel === 'tokens.css' ? 'styles/tokens.css' : /\.css$/.test(rel) || rel.startsWith('assets/fonts/') ? 'styles/' + rel.replace(/^assets\//, '') : 'public/' + rel);
  const webUrl = (u, name) => { const m = mapUrl(u, name); if (typeof m !== 'string' || !m.startsWith('/') || m.startsWith('//')) return m; const rel = m.slice(1).split(/[?#]/)[0]; return /\.(css|woff2?)$/.test(rel) || rel === 'tokens.css' ? '/' + pkgPath(rel) : m; };
  const { sheets } = headAssets(ir);
  const data = mapIR(ir, mapUrl, routes);
  const slug = ir.site.slug;
  // styles
  files.set('styles/tokens.css', ir.tokens.css);
  for (const a of ir.assets) files.set(pkgPath(a.path), readBin(opts.themeDir, a.path));
  const { scripts } = headAssets(ir);
  const inlineHead = ir.pages[0].headExtra.filter((h) => /^<script(?![^>]*\bsrc=)(?![^>]*ld\+json)/i.test(h));
  if (inlineHead.length) notes.push(`the theme runs ${inlineHead.length} inline script(s) in <head> (e.g. ${inlineHead[0].slice(0, 80)}): add them to your root layout's <head>`);
  if (scripts.length) notes.push(`the theme loads ${scripts.map((x) => '/' + x.path).join(', ')} (copied to public/): add it to your root layout as a script tag${scripts.some((x) => x.defer) ? ' with defer' : ''}`);
  files.set('public/favicon.svg', faviconSvg(ir));
  // the theme preloads its fonts in <head>; a bundler re-hashes the woff2 files, so the preload cannot be copied 1:1.
  // With font-display: optional and no preload the fallback font stays on a first visit.
  const preloads = (ir.pages[0].headExtra || []).filter((h) => /rel="?preload[^>]*\.woff2/i.test(h)).length;
  if (preloads && /font-display:\s*optional/i.test(ir.css.fonts || '')) notes.push(`the theme preloads ${preloads} font file(s) and uses font-display: optional: preload the same woff2 files in your framework (Next.js: next/font/local or a <link rel="preload"> to a file in public/), otherwise first visits render the fallback font`);
  const tw = toTailwindTheme(ir.tokens.dtcg);
  const twOrder = tailwindImports(sheets.map((h) => pkgPath(h)));
  files.set('styles/theme.css', `/* ${ir.site.name}: Tailwind v4 theme + shadcn/ui variables, generated by kk export from tokens.json.\n   Import order in your global CSS (see AGENTS.md): ${twOrder.join(' ')} */\n${tw}\n${shadcnCss(ir.tokens.dtcg, ir.css.site)}`);
  files.set('styles/index.css', `/* Without Tailwind: import this one file. Same order as the theme's pages. */\n${sheets.map((h) => `@import "./${pkgPath(h).replace(/^styles\//, '')}";`).join('\n')}\n`);
  // content and components
  for (const [name, s] of Object.entries(ir.sections)) if (s.props.length) files.set(`components/content/sections/${name}.json`, JSON.stringify(data.sections[name], null, 2) + '\n');
  for (const c of Object.values(ir.collections)) files.set(`components/content/${c.name}.json`, JSON.stringify(data.collections[c.name].items, null, 2) + '\n');
  for (const s of Object.values(ir.sections)) files.set(`components/${s.component}.tsx`, componentTsx(ir, s, mapUrl));
  files.set('components/index.ts', Object.values(ir.sections).map((s) => `export { default as ${s.component} } from './${s.component}';`).join('\n') + '\n');
  const pages = [];
  for (const page of ir.pages) { const p = pageTsx(ir, page, (h) => legalLinks(mapUrlsInHtml(h, mapUrl), routes)); pages.push({ ...p, page }); files.set(`pages/${p.name}.tsx`, p.code); }
  files.set('pages/index.ts', pages.map((p) => `export { default as ${p.name}, meta as ${p.name.replace(/Page$/, '')}Meta } from './${p.name}';`).join('\n') + '\n');
  // package, docs
  files.set('package.json', JSON.stringify({
    name: `@site/${slug}`, version: '0.1.0', private: true, type: 'module', description: `${ir.site.name}: design system and sections (generated by kk export)`,
    exports: { './styles/*': './styles/*', './components': './components/index.ts', './components/*': './components/*.tsx', './pages': './pages/index.ts' },
    peerDependencies: { react: '>=18' },
    devDependencies: { react: '^19.2.0', 'react-dom': '^19.2.0', esbuild: '^0.25.0', '@types/react': '^19.2.0' },
    scripts: { preview: 'node scripts/render-preview.mjs' },
  }, null, 2) + '\n');
  files.set('tsconfig.json', JSON.stringify({ compilerOptions: { target: 'ES2022', module: 'ESNext', moduleResolution: 'Bundler', jsx: 'react-jsx', strict: true, resolveJsonModule: true, esModuleInterop: true, skipLibCheck: true, noEmit: true }, include: ['components', 'pages'] }, null, 2) + '\n');
  files.set('scripts/render-preview.mjs', previewScript(ir, pages, webUrl));
  files.set('DESIGN.md', ir.design || '');
  files.set('AGENTS.md', agentsMdReact(ir, pages, { twOrder, scripts, inlineHead, bodyClass: bodyClass(ir.pages[0]) }));
  files.set('.gitignore', 'node_modules/\npreview/\n.kk/\n');
  // shadcn registry
  const roles = shadcnRoles(ir.tokens.dtcg, ir.css.site);
  const themeItem = { $schema: 'https://ui.shadcn.com/schema/registry-item.json', name: `${slug}-theme`, type: 'registry:theme', title: `${ir.site.name} theme`, description: ir.site.description, cssVars: { theme: roles.theme, light: roles.literal.light, ...(roles.literal.dark ? { dark: roles.literal.dark } : {}) } };
  const compFiles = [...Object.values(ir.sections).map((s) => ({ path: `components/${s.component}.tsx`, type: 'registry:component', target: `components/${slug}/${s.component}.tsx` })), ...[...files.keys()].filter((k) => k.startsWith('components/content/')).map((k) => ({ path: k, type: 'registry:file', target: `components/${slug}/${k.slice('components/'.length)}` }))];
  const blockItem = { $schema: 'https://ui.shadcn.com/schema/registry-item.json', name: `${slug}-sections`, type: 'registry:block', title: `${ir.site.name} sections`, description: 'Section components with their content. Needs the theme item and the fonts/CSS from styles/.', registryDependencies: [], files: compFiles };
  files.set('registry.json', JSON.stringify({ $schema: 'https://ui.shadcn.com/schema/registry.json', name: slug, homepage: ir.site.url || '', items: [themeItem, blockItem] }, null, 2) + '\n');
  files.set(`r/${slug}-theme.json`, JSON.stringify(themeItem, null, 2) + '\n');
  files.set(`r/${slug}-sections.json`, JSON.stringify({ ...blockItem, files: compFiles.map((f) => ({ ...f, content: String(files.get(f.path)) })) }, null, 2) + '\n');
  notes.push('documented React path: drop styles/, components/ and public/assets into an existing Next.js, TanStack Start (Lovable), Vite (Bolt) or v0 project; see AGENTS.md. No framework scaffold is generated.');
  notes.push(`shadcn registry: host r/${slug}-theme.json and r/${slug}-sections.json anywhere (your own server or repo) and run \`npx shadcn add <url>\`; fonts and styles/site.css are not part of the registry (binary files) and must be copied`);
  if (!roles.dark) notes.push('the theme has no dark band: shadcn .dark variables are not generated');
  notes.push('pages/*.tsx keep the theme\'s body markup; add <title>/<meta> through your framework (meta export per page)');
  // preview: same data rendered as static HTML; --build renders the real TSX with react-dom/server
  const preview = new Map();
  for (const page of ir.pages) preview.set(page.slug === 'index' ? 'index.html' : `${page.slug}/index.html`, pageHtml(ir, page, renderBody(ir, page, mapUrl, routes, data), { mapUrl }));
  preview.set('tokens.css', ir.tokens.css);
  for (const a of ir.assets) preview.set(a.path, readBin(opts.themeDir, a.path));
  return { files, notes, postCheck: { buildCmd: 'npm install --no-audit --no-fund && npm run preview', buildDir: 'preview', pages: ir.pages.filter((p) => p.slug !== '404').map((p) => p.path), sourcePages: ir.pages.filter((p) => p.slug !== '404').map((p) => p.file), preview: { files: preview, pages: ir.pages.filter((p) => p.slug !== '404').map((p) => p.path) } } };
}

function previewScript(ir, pages, webUrl) {
  return `// Renders the TSX pages to static HTML with react-dom/server (kk export --build uses this for the check).
import { build } from 'esbuild';
import { mkdirSync, writeFileSync, cpSync, existsSync } from 'node:fs';
import { createElement } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';

const pages = ${JSON.stringify(pages.map((p) => ({ name: p.name, path: p.page.path, title: pageTitle(ir, p.page), description: p.page.description, bodyOpen: p.page.bodyOpen, head: [...headExtraBefore(p.page, webUrl), ...(p.page.stylesheets || []).map((h) => `<link rel="stylesheet" href="${webUrl(h, 'href')}">`), ...headExtraAfter(p.page, webUrl)].join('\n') })))};
await build({ entryPoints: ['pages/index.ts'], bundle: true, platform: 'node', format: 'esm', outfile: '.kk/pages.mjs', jsx: 'automatic', loader: { '.json': 'json' }, external: ['react', 'react-dom'], logLevel: 'warning' });
const mod = await import(new URL('../.kk/pages.mjs', import.meta.url));
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
for (const p of pages) {
  const html = '<!doctype html>\\n<html lang=${JSON.stringify(ir.site.lang)}>\\n<head>\\n<meta charset="utf-8">\\n<meta name="viewport" content="width=device-width, initial-scale=1">\\n<title>' + esc(p.title) + '</title>\\n<meta name="description" content="' + esc(p.description) + '">\\n' + (/rel="icon"/.test(p.head) ? '' : '<link rel="icon" href="/favicon.svg" type="image/svg+xml">\\n') + p.head + '\\n</head>\\n' + (p.bodyOpen || '<body>') + '\\n' + renderToStaticMarkup(createElement(mod[p.name])) + '\\n</body>\\n</html>\\n';
  const dir = 'preview' + (p.path === '/' ? '' : p.path);
  mkdirSync(dir, { recursive: true });
  writeFileSync(dir + '/index.html', html);
}
cpSync('styles', 'preview/styles', { recursive: true });
if (existsSync('public')) cpSync('public', 'preview', { recursive: true });
console.log('preview written to preview/');
`;
}

/** Global CSS for Tailwind v4 in the theme's own stylesheet order, theme.css right after tokens.css. Preflight stays off:
 * it resets headings, lists and images, which the theme's CSS does not expect. */
export function tailwindImports(pkgSheets) {
  const order = pkgSheets.length ? [...pkgSheets] : ['styles/tokens.css'];
  if (!order.includes('styles/tokens.css')) order.unshift('styles/tokens.css');
  order.splice(order.indexOf('styles/tokens.css') + 1, 0, 'styles/theme.css');
  return ['@layer theme, base, components, utilities;', '@import "tailwindcss/theme.css" layer(theme);', '@import "tailwindcss/utilities.css" layer(utilities);', ...order.map((p) => `@import "./${p}";`)];
}

function agentsMdReact(ir, pages, { twOrder = [], scripts = [], inlineHead = [], bodyClass: bc = '' } = {}) {
  const slug = ir.site.slug;
  return `# ${ir.site.name}: React drop-in

Generated by \`kk export --target react\`. Plain React + TSX, no framework lock-in. Read DESIGN.md before changing anything visual.

## Use it
1. Copy \`styles/\`, \`components/\` and \`public/assets/\` into the project (or add this folder as a workspace package).
2. Fonts: the theme preloads its woff2 files and may use font-display: optional. Preload them in your framework (Next.js: next/font/local; Vite: a <link rel="preload" as="font" crossorigin> in index.html to a copy in public/), or first visits show the fallback font.
3. Global CSS (paths relative to where you copied \`styles/\`):
   - with Tailwind v4, in this order (the theme's stylesheet order, fonts included; theme.css right after tokens.css):
     \`\`\`css
${twOrder.map((l) => '     ' + l).join('\n')}
     \`\`\`
     Preflight (Tailwind's base reset) is left out on purpose: it resets headings, lists and images, and the theme's CSS
     does not expect that. If your project already imports \`tailwindcss\` as a whole, check headings and lists against the
     design. The theme's CSS is not in a layer, so it wins over Tailwind utilities on the same element.
   - without Tailwind: \`import './styles/index.css'\` once in the root layout (same order, fonts included).
   - Body class: each page exports \`meta.bodyClassName\`${bc ? ` (home: \`${bc}\`)` : ''} and \`meta.bodyId\`. Put them on \`<body>\` in your layout; parts of the theme's CSS select on them.
${scripts.length ? `   - Script: the theme loads ${scripts.map((x) => '\`/' + x.path + '\`').join(', ')} (copied to \`public/\`). Add ${scripts.map((x) => `\`<script src="/${x.path}"${x.defer ? ' defer' : ''}${x.async ? ' async' : ''}></script>\``).join(', ')} to the root layout (Next.js: \`<Script src="/${scripts[0].path}" strategy="afterInteractive" />\`); menus, toggles and reveal effects depend on it.\n` : ''}${inlineHead.length ? `   - Inline script in <head> (${inlineHead.length}): copy it from the theme page into the root layout's <head> (it usually sets a class before the first paint).\n` : ''}
4. Render a page component (\`pages/${pages[0]?.name}.tsx\`) in a route, or compose sections yourself: \`import { ${Object.values(ir.sections).slice(0, 3).map((s) => s.component).join(', ')} } from './components'\`.
   - Next.js (App Router): import the global CSS in \`app/layout.tsx\`; \`app/page.tsx\` returns \`<${pages[0]?.name} />\`; set metadata from the page's \`meta\` export. Keep the woff2 files local (no next/font/google).
   - TanStack Start (Lovable): import the CSS in the root route, render the page component in \`routes/index.tsx\`.
   - Vite (Bolt): import the CSS in \`main.tsx\`.
   - v0 / shadcn: \`npx shadcn add <your-host>/r/${slug}-theme.json\` and \`.../r/${slug}-sections.json\`, then copy \`styles/fonts\` and \`styles/site.css\`.

## Rules
- Tokens only: colours and type come from styles/tokens.css (generated from tokens.json). shadcn variables (\`--background\`, \`--primary\` …) are aliases of them; never type a new colour, never use Tailwind's default palette (it is reset in theme.css).
- No third-party requests: fonts are self-hosted, no CDN, no embeds without a two-click facade, no analytics unless decided (cookie-free, first-party).
- Impressum and Datenschutz must be linked from every page footer (routes /impressum/ and /datenschutz/; create them in your app).
- Texts live in components/content/*.json. Change wording there.
- Check: \`npm install && npm run preview\` renders the pages to preview/; run \`kk check\` on them and \`kk launch <url>\` once deployed.
`;
}
